            p = 0
            if s[i] == "D":
                for ind in range(val + 1): 
                    p = (p + dfs(i + 1, ind)) % (10**9 + 7)
            else:
                for ind in range(val + 1, i + 2): 
                    p = (p + dfs(i + 1, ind)) % (10**9 + 7)
            mem[i, val] = p
            return p
        return dfs(0)
