    def countSubgraphsForEachDiameter(self, n: int, edges: List[List[int]]) -> List[int]:
        adj = [[] for i in range(n)]
        for u,v in edges:
            adj[u-1].append(v-1)
            adj[v-1].append(u-1)

        def comb(p,q): 
            if len(q)<len(p): p,q = q,p
            res = [0]*len(q)
            res[0] = p[0]*q[0]
            p_prefix = p[:]
            q_prefix = q[:]
            for i in range(1,len(p_prefix)): p_prefix[i] += p_prefix[i-1]
            for i in range(1,len(q_prefix)): q_prefix[i] += q_prefix[i-1]
            for i in range(1,len(p)):
                res[i] = p_prefix[i]*q_prefix[i]-p_prefix[i-1]*q_prefix[i-1]
            for i in range(len(p),len(q)):
                res[i] = (q_prefix[i]-q_prefix[i-1])*p_prefix[-1]
            return res

        def dfs(r,p): 
            d = [1]
            for v in adj[r]:
                if v==p: continue
                t = [1]+dfs(v,r)
                d = comb(t,d)
            return d

